import 'package:dart_style/dart_style.dart';
import 'package:pub_semver/pub_semver.dart';

import 'api_model.dart';

/// The language version of the playground package (its SDK constraint), the
/// generated file is formatted like `dart format` does it there.
final _languageVersion = Version(3, 8, 0);

/// The documented classes for the playground
/// (`playground/lib/generated/api_registry.g.dart`): their properties, and
/// how to read them and copy an instance with some of them changed.
String registryDart(Iterable<ApiType> types) {
  final classes = types.where((t) => t.mode == TableMode.constructor).toList()
    ..sort((a, b) => a.name.compareTo(b.name));
  final copyable = classes.where((t) => t.copyIssue == null).toList();
  final usesDeprecated = copyable.any(
    (t) => t.members.any((m) => m.deprecationMessage != null),
  );

  const header =
      '// Generated by tool/api_docs from the dartdoc, run `make docs`.';
  final out = StringBuffer()
    ..writeln(header)
    ..writeln(usesDeprecated ? '// ignore_for_file: deprecated_member_use' : '')
    ..writeln()
    ..writeln("import 'dart:ui' as ui;")
    ..writeln()
    ..writeln("import 'package:fl_chart/fl_chart.dart';")
    ..writeln("import 'package:flutter/material.dart';")
    ..writeln()
    ..writeln("import '../src/api.dart';")
    ..writeln()
    ..writeln('/// The documented classes of fl_chart, by name.')
    ..writeln('final apiRegistry = <String, ClassSpec>{');
  for (final type in classes) {
    out
      ..writeln('${_str(type.name)}: ClassSpec(name: ${_str(type.name)},')
      ..writeln('properties: const [');
    for (final m in type.members) {
      final arguments = [
        'name: ${_str(m.name)}',
        'type: ${_str(m.type!)}',
        'kind: PropertyKind.${m.kind.name}',
        if (m.isNullable) 'isNullable: true',
        if (m.isRequired) 'isRequired: true',
        if (m.isPositional) 'isPositional: true',
        if (m.kind == PropertyKind.enumeration) 'values: ${m.kindType}.values',
        if (m.kind == PropertyKind.nested) 'nestedType: ${_str(m.kindType!)}',
        if (m.defaultValue != null) 'defaultCode: ${_str(m.defaultValue!)}',
      ];
      out.writeln('PropertySpec(${arguments.join(', ')}),');
    }
    out.writeln('],');
    if (type.copyIssue == null) {
      out.writeln('read: _read${type.name}, copy: _copy${type.name},');
    }
    out.writeln('),');
  }
  out.writeln('};');

  for (final type in copyable) {
    final name = type.name;
    out
      ..writeln()
      ..writeln('Object? _read$name(Object instance, String property) {')
      ..writeln('final o = instance as $name;')
      ..writeln('return switch (property) {');
    for (final m in type.members) {
      out.writeln('${_str(m.name)} => o.${m.name},');
    }
    out
      ..writeln("_ => throw ArgumentError.value(property, 'property'),")
      ..writeln('};')
      ..writeln('}')
      ..writeln()
      ..writeln(
        '$name _copy$name(Object instance, Map<String, Object?> values) {',
      )
      ..writeln('final o = instance as $name;')
      ..writeln('return $name(');
    for (final m in type.members) {
      final value =
          '_value<${m.typeCode}>(values, ${_str(m.name)}, o.${m.name})';
      out.writeln(m.isPositional ? '$value,' : '${m.name}: $value,');
    }
    out
      ..writeln(');')
      ..writeln('}');
  }

  out
    ..writeln()
    ..writeln(
      'T _value<T>(Map<String, Object?> values, String name, T current) =>',
    )
    ..writeln('values.containsKey(name) ? values[name] as T : current;');

  return DartFormatter(languageVersion: _languageVersion)
      .format(out.toString());
}

/// A Dart string literal of [value].
String _str(String value) {
  final escaped = value
      .replaceAll(r'\', r'\\')
      .replaceAll("'", r"\'")
      .replaceAll(r'$', r'\$')
      .replaceAll('\n', r'\n');
  return "'$escaped'";
}
